source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    enclosed = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 0 and (r,c) not in outside}
    components = []
    unseen = set(enclosed)
    while unseen:
        start = unseen.pop()
        component = {start}
        q = deque([start])
        while q:
            r,c=q.popleft()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in unseen:
                    unseen.remove((nr,nc)); component.add((nr,nc)); q.append((nr,nc))
        components.append(component)
    out = [row[:] for row in grid]
    color_by_width = {3: 8, 5: 4, 7: 3}
    for component in components:
        width = max(c for r,c in component) - min(c for r,c in component) + 1
        height = max(r for r,c in component) - min(r for r,c in component) + 1
        color = color_by_width[width]
        for r,c in component:
            out[r][c] = color
    return out
'''
